def transform(grid):
    h, w = len(grid), len(grid[0])

    # A uniform divider column separates equal-width panels.
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and c > 0 and w - c - 1 == c:
            left_bg = max((grid[r][j] for r in range(h) for j in range(c)),
                          key=lambda x: sum(row[:c].count(x) for row in grid))
            out = []
            for r in range(h):
                out.append([3 if grid[r][j] == grid[r][c + 1 + j] else left_bg
                            for j in range(c)])
            return out

    # A uniform divider row separates equal-height panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and r > 0 and h - r - 1 == r:
            upper, lower = grid[:r], grid[r + 1:]
            bg = max((x for row in upper for x in row),
                     key=lambda x: sum(row.count(x) for row in upper))
            return [[3 if upper[i][j] == lower[i][j] else bg
                     for j in range(w)] for i in range(r)]

    return grid
